package com.itemstatsfilter;

/**
 * How an item whose stats are hidden is marked. Declaration order is the dropdown order.
 */
public enum HiddenStatsIndicator
{
	ASTERISK("Asterisk"),
	MARKER_BOX("Marker box"),
	NONE("None");

	private final String displayName;

	HiddenStatsIndicator(String displayName)
	{
		this.displayName = displayName;
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

